impl Solution {
    pub fn is_long_pressed_name(name: String, typed: String) -> bool {
        let (m, n) = (name.len(), typed.len());
        let (mut i, mut j) = (0, 0);
        let s: Vec<char> = name.chars().collect();
        let t: Vec<char> = typed.chars().collect();

        while i < m && j < n {
            if s[i] != t[j] {
                return false;
            }
            let mut x = i + 1;
            while x < m && s[x] == s[i] {
                x += 1;
            }
            let mut y = j + 1;
            while y < n && t[y] == t[j] {
                y += 1;
            }
            if x - i > y - j {
                return false;
            }
            i = x;
            j = y;
        }

        i == m && j == n
    }
}

package io.github.leetcode.strings;

public class LongPressedName {

    public boolean isLongPressedName(String name, String typed) {
        if(name.equals(typed)){
            return true;
        }

        if(typed.length() < name.length()){
            return false;
        }

        int i = 0, j = 0;
        while(j < typed.length()){
            if(i < name.length() && name.charAt(i) == typed.charAt(j)){
                i++;
                j++;
            } else if(j > 0 && typed.charAt(j) == typed.charAt(j - 1)){
                j++;
            } else {
                return false;
            }
        }

        return i == name.length();
    }

}

class Solution(object):
    def isLongPressedName(self, name, typed):
        """
        :type name: str
        :type typed: str
        :rtype: bool
        """
        p1 = p2 = 0
        while p1 < len(name) and p2 < len(typed):
            cnt1 = cnt2 = 1
            if name[p1] != typed[p2]:
                return False
            while p1 + 1 < len(name) and name[p1] == name[p1 + 1]:
                cnt1 += 1
                p1 += 1
            while p2 + 1 < len(typed) and typed[p2] == typed[p2 + 1]:
                cnt2 += 1
                p2 += 1
            if cnt1 > cnt2:
                return False
            p1 += 1
            p2 += 1
        if p1 < len(name) or p2 < len(typed):
            return False
        return True
